import{_ as t,a0 as o,w as d,s as r,ao as l,I as p,a1 as e,A as i,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"如何在 Linux 中使用 LVM 創建和擴展交換分區 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中使用 LVM 創建和擴展交換分區 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中使用 LVM 創建和擴展交換分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中使用 LVM 創建和擴展交換分區 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180328 How To Create-Extend Swap Partition In Linux Using LVM","title":"如何在 Linux 中使用 LVM 創建和擴展交換分區","tag":"201804","desc":""},"relativePath":"201804/20180328 How To Create-Extend Swap Partition In Linux Using LVM.md","filePath":"[post].md"}'),g={name:"201804/20180328 How To Create-Extend Swap Partition In Linux Using LVM.md"};function h(u,s,c,k,b,f){const n=o("Link");return d(),r("div",null,[s[15]||(s[15]=l('<h1 id="如何在-linux-中使用-lvm-創建和擴展交換分區" tabindex="-1">如何在 Linux 中使用 LVM 創建和擴展交換分區 <a class="header-anchor" href="#如何在-linux-中使用-lvm-創建和擴展交換分區" aria-label="Permalink to “如何在 Linux 中使用 LVM 創建和擴展交換分區”">​</a></h1><p>我們使用 LVM 進行靈活的卷管理，為什麼我們不能將 LVM 用於交換分區呢？</p><p>這可以讓用户在需要時增加交換分區。如果你升級系統中的內存，則需要添加更多交換空間。這有助於你管理運行需要大量內存的應用的系統。</p><p>可以通過三種方式創建交換分區</p><ul><li>創建一個新的交換分區</li><li>創建一個新的交換文件</li><li>在現有邏輯卷（LVM）上擴展交換分區</li></ul><p>建議創建專用交換分區而不是交換文件。</p><p><strong>建議閲讀：</strong></p>',7)),p("ul",null,[p("li",null,[e(n,{href:"https://www.2daygeek.com/add-extend-increase-swap-space-memory-file-partition-linux/"},{default:i(()=>[...s[0]||(s[0]=[a("3 種簡單的方法在 Linux 中創建或擴展交換空間",-1)])]),_:1})]),p("li",null,[e(n,{href:"https://www.2daygeek.com/shell-script-create-add-extend-swap-space-linux/"},{default:i(()=>[...s[1]||(s[1]=[a("使用 Shell 腳本在 Linux 中自動創建/刪除和掛載交換文件",-1)])]),_:1})])]),s[16]||(s[16]=l(`<p>Linux 中推薦的交換大小是多少？</p><h3 id="什麼是交換空間" tabindex="-1">什麼是交換空間 <a class="header-anchor" href="#什麼是交換空間" aria-label="Permalink to “什麼是交換空間”">​</a></h3><p>當物理內存 （RAM） 已滿時，將使用 Linux 中的交換空間。當物理內存已滿時，內存中的非活動頁將移到交換空間。</p><p>這有助於系統連續運行應用程序，但它不能當做是更多內存的替代品。</p><p>交換空間位於硬盤上，因此它不能像物理內存那樣處理請求。</p><h3 id="如何使用-lvm-創建交換分區" tabindex="-1">如何使用 LVM 創建交換分區 <a class="header-anchor" href="#如何使用-lvm-創建交換分區" aria-label="Permalink to “如何使用 LVM 創建交換分區”">​</a></h3><p>由於我們已經知道如何創建邏輯卷，所以交換分區也是如此。只需按照以下過程。</p><p>創建你需要的邏輯卷。在我這裏，我要創建 <code>5GB</code> 的交換分區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvcreate -L 5G -n LogVol_swap1 vg00</span></span>
<span class="line"><span> Logical volume &quot;LogVol_swap1&quot; created.</span></span></code></pre></div><p>格式化新的交換空間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /dev/vg00/LogVol_swap1</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 5 GiB (5368705024 bytes)</span></span>
<span class="line"><span>no label, UUID=d278e9d6-4c37-4cb0-83e5-2745ca708582</span></span></code></pre></div><p>將以下條目添加到 <code>/etc/fstab</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># vi /etc/fstab</span></span>
<span class="line"><span>/dev/mapper/vg00-LogVol_swap1 swap swap defaults 0 0</span></span></code></pre></div><p>啓用擴展邏輯卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon -va</span></span>
<span class="line"><span>swapon: /swapfile: already active -- ignored</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: found signature [pagesize=4096, signature=swap]</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: pagesize=4096, swapsize=5368709120, devsize=5368709120</span></span>
<span class="line"><span>swapon /dev/mapper/vg00-LogVol_swap1</span></span></code></pre></div><p>測試交換空間是否已正確添加。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/swaps</span></span>
<span class="line"><span>Filename                Type        Size    Used    Priority</span></span>
<span class="line"><span>/swapfile file      1459804 526336  -1</span></span>
<span class="line"><span>/dev/dm-0 partition 5242876 0   -2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ free -g</span></span>
<span class="line"><span> total used free shared buff/cache available</span></span>
<span class="line"><span>Mem: 1 1 0 0 0 0</span></span>
<span class="line"><span>Swap: 6 0 6</span></span></code></pre></div><h3 id="如何使用-lvm-擴展交換分區" tabindex="-1">如何使用 LVM 擴展交換分區 <a class="header-anchor" href="#如何使用-lvm-擴展交換分區" aria-label="Permalink to “如何使用 LVM 擴展交換分區”">​</a></h3><p>只需按照以下過程來擴展 LVM 交換邏輯卷。</p><p>禁用相關邏輯卷的交換。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapoff -v /dev/vg00/LogVol_swap1</span></span>
<span class="line"><span>swapoff /dev/vg00/LogVol_swap1</span></span></code></pre></div><p>調整邏輯卷的大小。我將把交換空間從 <code>5GB</code> 增加到 <code>11GB</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvresize /dev/vg00/LogVol_swap1 -L +6G</span></span>
<span class="line"><span> Size of logical volume vg00/LogVol_swap1 changed from 5.00 GiB (1280 extents) to 11.00 GiB (2816 extents).</span></span>
<span class="line"><span> Logical volume vg00/LogVol_swap1 successfully resized.</span></span></code></pre></div><p>格式化新的交換空間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /dev/vg00/LogVol_swap1</span></span>
<span class="line"><span>mkswap: /dev/vg00/LogVol_swap1: warning: wiping old swap signature.</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 11 GiB (11811155968 bytes)</span></span>
<span class="line"><span>no label, UUID=2e3b2ee0-ad0b-402c-bd12-5a9431b73623</span></span></code></pre></div><p>啓用擴展邏輯卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon -va</span></span>
<span class="line"><span>swapon: /swapfile: already active -- ignored</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: found signature [pagesize=4096, signature=swap]</span></span>
<span class="line"><span>swapon: /dev/mapper/vg00-LogVol_swap1: pagesize=4096, swapsize=11811160064, devsize=11811160064</span></span>
<span class="line"><span>swapon /dev/mapper/vg00-LogVol_swap1</span></span></code></pre></div><p>測試邏輯卷是否已正確擴展。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -g</span></span>
<span class="line"><span> total used free shared buff/cache available</span></span>
<span class="line"><span>Mem: 1 1 0 0 0 0</span></span>
<span class="line"><span>Swap: 12 0 12</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat /proc/swaps</span></span>
<span class="line"><span>Filename                Type        Size    Used    Priority</span></span>
<span class="line"><span>/swapfile file      1459804 237024  -1</span></span>
<span class="line"><span>/dev/dm-0 partition 11534332    0   -2</span></span></code></pre></div><hr>`,30)),p("p",null,[s[3]||(s[3]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/how-to-create-extend-swap-partition-in-linux-using-lvm/"},{default:i(()=>[...s[2]||(s[2]=[a("https://www.2daygeek.com/how-to-create-extend-swap-partition-in-linux-using-lvm/",-1)])]),_:1})]),p("p",null,[s[7]||(s[7]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/ramya/"},{default:i(()=>[...s[4]||(s[4]=[a("Ramya Nuvvula",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[5]||(s[5]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[6]||(s[6]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const L=t(g,[["render",h]]);export{m as __pageData,L as default};
